const d=$json;
const a=d.email_authorization??{};
const b=d.delivery_request?.response_body??{};
const r=b.report??{};
const p=b.presentation??{};
const esc=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const title=String(p.title??r.kpi_key??'Revenue Report').replace(/[\u0000-\u001f\u007f]/g,' ').trim();
let subject=('Revenue Report — '+title).slice(0,Number(a.max_subject_chars??180));
const parts=['<h2>'+esc(title)+'</h2>'];
if(p.summary) parts.push('<p>'+esc(p.summary)+'</p>');
if(Array.isArray(p.key_facts)&&p.key_facts.length) parts.push('<h3>Key facts</h3><ul>'+p.key_facts.slice(0,8).map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>');
const cp=r.current_period??{};
if(cp.value!==undefined&&cp.value!==null) parts.push('<p><strong>Current value:</strong> '+esc(cp.value)+(r.currency_code?' '+esc(r.currency_code):(r.unit?' '+esc(r.unit):''))+'</p>');
const rows=p.data?.rows;
if(Array.isArray(rows)&&rows.length){
  parts.push('<h3>Data preview</h3><pre>'+esc(rows.slice(0,10).map(x=>JSON.stringify(x)).join('\n')).slice(0,8000)+'</pre>');
}
const body=parts.join('\n').slice(0,Number(a.max_body_chars??20000));
const valid=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(a.recipient_email??'')) && subject.length>0 && body.length>0 && body.length<=Number(a.max_body_chars??20000);
return {...d,email_payload:{send_to:a.recipient_email,subject,html:body},email_payload_validation:{valid,subject_length:subject.length,body_length:body.length}};
